/* ------------------------------------------------------------------ */
/*  Seed runner                                                        */
/* ------------------------------------------------------------------ */

async function seed() {
  console.log("Connecting to database...");
  await connectDB();

  let totalInserted = 0;

  for (const [role, questions] of Object.entries(questionBank)) {
    // Always clear and re-seed to pick up any changes
    await InterviewQuestion.deleteMany({ role });

    const docs = questions.map((q) => ({
      role,
      theme: q.theme,
      questionTemplate: q.questionTemplate,
      answerTemplate: q.answerTemplate,
      difficulty: q.difficulty || "medium",
      tags: q.tags || [],
    }));

    await InterviewQuestion.insertMany(docs);
    console.log(`  ✓ ${role}: inserted ${docs.length} questions.`);
    totalInserted += docs.length;
  }

  console.log(`\nDone! Total inserted: ${totalInserted}`);

  // Summary
  const counts = await InterviewQuestion.aggregate([
    { $group: { _id: "$role", count: { $sum: 1 } } },
    { $sort: { _id: 1 } },
  ]);

  console.log("\nQuestion bank summary:");
  counts.forEach((item) => console.log(`  ${item._id}: ${item.count} questions`));

  await mongoose.disconnect();
  console.log("\nDatabase disconnected. Seed complete.");
}

seed().catch((err) => {
  console.error("Seed failed:", err);
  process.exit(1);
});
